"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatDashboardValue, shareOf } from "@/lib/dashboard-format"

export type TierTone = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5" | "primary" | "destructive"

export type TierDistributionTier = {
  id: string
  label: string
  value: number
  tone?: TierTone
}

export type TierDistributionClassNames = {
  root?: string
  option?: string
  block?: string
  label?: string
  value?: string
}

export type TierDistributionProps = {
  tiers: readonly TierDistributionTier[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  label?: string
  locale?: string
  className?: string
  classNames?: TierDistributionClassNames
}

const toneClass: Record<TierTone, string> = {
  "chart-1": "bg-chart-1",
  "chart-2": "bg-chart-2",
  "chart-3": "bg-chart-3",
  "chart-4": "bg-chart-4",
  "chart-5": "bg-chart-5",
  primary: "bg-primary",
  destructive: "bg-destructive",
}

const fallbackTone: TierTone[] = ["chart-1", "chart-2", "chart-3", "chart-4"]

export function TierDistribution({
  tiers,
  value,
  defaultValue,
  onValueChange,
  label = "Distribution",
  locale = "en-US",
  className,
  classNames,
}: TierDistributionProps) {
  const list = tiers.slice(0, 4)
  const total = list.reduce((sum, tier) => sum + (Number.isFinite(tier.value) ? Math.max(0, tier.value) : 0), 0)
  const [internal, setInternal] = React.useState(defaultValue ?? list[0]?.id ?? "")
  const selected = value ?? internal
  const active = list.some((tier) => tier.id === selected) ? selected : list[0]?.id ?? ""

  function select(id: string) {
    if (value === undefined) setInternal(id)
    onValueChange?.(id)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    const keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp", "Home", "End"]
    if (!keys.includes(event.key)) return
    if (!list.length) return
    event.preventDefault()
    const index = Math.max(0, list.findIndex((tier) => tier.id === active))
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? list.length - 1
          : event.key === "ArrowRight" || event.key === "ArrowDown"
            ? (index + 1) % list.length
            : (index - 1 + list.length) % list.length
    const id = list[next]?.id
    if (!id) return
    select(id)
    const node = event.currentTarget.querySelector<HTMLElement>(`[data-tier-id="${CSS.escape(id)}"]`)
    node?.focus()
  }

  return (
    <div
      data-slot="tier-distribution"
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={cn("@container flex min-w-0 flex-wrap items-end gap-2", className, classNames?.root)}
    >
      {list.length === 0 ? <p className="text-sm text-muted-foreground">No tiers</p> : null}
      {list.map((tier, index) => {
        const share = shareOf(Math.max(0, tier.value), total)
        const tone = tier.tone ?? fallbackTone[index % fallbackTone.length]
        const checked = tier.id === active
        const count = formatDashboardValue(tier.value, "number", locale)
        const percent = formatDashboardValue(share, "percent", locale)
        return (
          <button
            key={tier.id}
            type="button"
            role="radio"
            data-tier-id={tier.id}
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            onClick={() => select(tier.id)}
            style={{ flexGrow: Math.max(share, 0.2), flexBasis: "6.5rem" }}
            className={cn(
              "flex min-w-[6.5rem] flex-col gap-2 rounded-xl p-2 text-start focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              checked ? "bg-muted" : "hover:bg-muted/60",
              classNames?.option,
            )}
          >
            <span className="flex items-baseline justify-between gap-2">
              <span className={cn("text-sm font-medium break-words", classNames?.label)}>{tier.label}</span>
              <span className={cn("text-sm tabular-nums", classNames?.value)}>{count}</span>
            </span>
            <span
              data-slot="tier-distribution-block"
              className={cn(
                "block h-12 w-full min-w-2 rounded-md bg-gradient-to-t from-background/40 to-transparent",
                toneClass[tone],
                classNames?.block,
              )}
              aria-hidden
            />
            <span className="text-xs text-muted-foreground tabular-nums">{percent}</span>
          </button>
        )
      })}
    </div>
  )
}

/** Number, date, and greeting helpers for dashboard pieces. No theme tokens. */

export type DashboardFormat = "number" | "currency" | "percent" | "compact" | "text" | "points"

export function formatDashboardValue(
  value: number | string,
  format: DashboardFormat = "text",
  locale = "en-US",
  currency = "USD",
): string {
  if (typeof value !== "number" || !Number.isFinite(value) || format === "text") return String(value)
  if (format === "currency") {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      notation: Math.abs(value) >= 10000 ? "compact" : "standard",
      maximumFractionDigits: Math.abs(value) >= 10000 ? 1 : 0,
    }).format(value)
  }
  if (format === "percent") {
    return new Intl.NumberFormat(locale, {
      style: "percent",
      maximumFractionDigits: 1,
    }).format(value)
  }
  if (format === "compact") {
    return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value)
  }
  if (format === "points") {
    const formatted = new Intl.NumberFormat(locale, {
      signDisplay: "exceptZero",
      maximumFractionDigits: 1,
    }).format(value)
    return `${formatted} pts`
  }
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)
}

export function formatDashboardDate(
  value: string | number | Date,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { month: "short", day: "numeric" },
): string {
  const date = value instanceof Date ? value : new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return new Intl.DateTimeFormat(locale, options).format(date)
}

export function joinMeta(parts: Array<string | number | null | undefined | false>): string {
  return parts.filter((part) => part != null && part !== false && part !== "").map(String).join(" · ")
}

const DAY_PART = {
  en: { morning: "Good morning", afternoon: "Good afternoon", evening: "Good evening" },
  es: { morning: "Buenos días", afternoon: "Buenas tardes", evening: "Buenas noches" },
} as const

/** Time-of-day greeting. Spanish locales use es; everything else uses en. */
export function greeting(date: Date, locale: string, name: string): string {
  const hour = date.getHours()
  const part = hour < 12 ? "morning" : hour < 18 ? "afternoon" : "evening"
  const table = locale.toLowerCase().startsWith("es") ? DAY_PART.es : DAY_PART.en
  return `${table[part]}, ${name}`
}

export function shareOf(value: number, total: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(total) || total <= 0) return 0
  return value / total
}

export function clampRatio(value: number, min: number, max: number): number {
  const span = max - min
  if (!Number.isFinite(span) || span <= 0) return 0
  return Math.min(1, Math.max(0, (value - min) / span))
}

export type RankedInput = { id: string; value: number; share?: number }

export function orderRanked<T extends RankedInput>(items: readonly T[], sort: "asc" | "desc" | "none" = "desc"): T[] {
  const copy = items.map((item) => ({ ...item }))
  if (sort === "asc") copy.sort((a, b) => a.value - b.value || a.id.localeCompare(b.id))
  if (sort === "desc") copy.sort((a, b) => b.value - a.value || a.id.localeCompare(b.id))
  const total = copy.reduce((sum, item) => sum + (Number.isFinite(item.value) ? item.value : 0), 0)
  return copy.map((item) => ({ ...item, share: item.share ?? shareOf(item.value, total) }))
}

/** Delay in seconds for a short opacity stagger. Zero when motion is reduced. */
export function staggerDelay(index: number, reduced: boolean, step = 0.04): number {
  if (reduced || index <= 0) return 0
  return index * step
}
